describe('ToolRegistry input validation', () => {
  it('names the property path and expected type when rejecting a wrong-typed field', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'unreachable');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      execute
    );

    const response = await registry.execute('get_weather', {location: 42});

    expect({response, calls: execute.mock.calls.length}).toEqual({
      response: {result: 'Tool input validation failed: /location must be string'},
      calls: 0,
    });
  });

  it('reports the full nested path for a missing required property', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'unreachable');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {
            request: {
              type: 'object',
              properties: {location: {type: 'string'}},
              required: ['location'],
            },
          },
          required: ['request'],
        },
      },
      execute
    );

    const response = await registry.execute('get_weather', {request: {}});

    expect({response, calls: execute.mock.calls.length}).toEqual({
      response: {result: 'Tool input validation failed: /request/location is required'},
      calls: 0,
    });
  });
